// Directional intra prediction WITH runtime angle_delta AND the intra edge
// filter / corner filter / edge upsample, vs the SW reference predictIntraRaw
// over the 8 directional modes x angle_delta -3..3, fully-available interior
// references (nTopPx = nLeftPx = bs). Covers:
//   - edge filter strength (runtime, from |pAngle-90|/|pAngle-180|),
//   - the corner filter (bs=16, z2 angles: 2*bs >= 24),
//   - edge upsample (bs=4/8: blkWh <= 16 luma, delta != 0, < 40),
//   - both replicate (nTopRight=0) and real (nTopRight=bs) top-right/bottom-left
//     extension.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  BigInt packB(List<int> b) {
    var v = BigInt.zero;
    for (var i = 0; i < b.length; i++) {
      v |= BigInt.from(b[i] & 0xff) << (i * 8);
    }
    return v;
  }

  for (final bs in [4, 8, 16]) {
    for (final realExt in [false, true]) {
      final tag = realExt ? 'realExt' : 'replExt';
      test(
        'HarborIntraDirEdge bs=$bs $tag matches predictIntraRaw (edge filter)',
        timeout: const Timeout(Duration(minutes: 20)),
        () async {
          final t = HarborIntraDirEdge(bs: bs);
          final clk = SimpleClockGenerator(10).clk;
          final mode = Logic(name: 'mode', width: 4);
          final ad = Logic(name: 'angle_delta', width: 4);
          final above = Logic(name: 'above', width: 2 * bs * 8);
          final left = Logic(name: 'left', width: 2 * bs * 8);
          final corner = Logic(name: 'corner', width: 8);
          final en = Logic(name: 'en');
          final ft = Logic(name: 'ft');
          t.input('mode').srcConnection! <= mode;
          t.input('angle_delta').srcConnection! <= ad;
          t.input('above').srcConnection! <= above;
          t.input('left').srcConnection! <= left;
          t.input('corner').srcConnection! <= corner;
          t.input('enable_edge_filter').srcConnection! <= en;
          t.input('filter_type').srcConnection! <= ft;
          await t.build();
          Simulator.setMaxSimTime(400000000);
          unawaited(Simulator.run());

          final rng = Random(0xED9E + bs + (realExt ? 1 : 0));
          var gi = 0;
          for (var iter = 0; iter < 12; iter++) {
            // Real edge pixels (bs) plus extension (bs). When !realExt the
            // extension replicates the last real pixel (nTopRight = 0), matching
            // libaom. When realExt the extension is real (nTopRight = bs).
            final aReal = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
            final lReal = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
            final aExt = [
              for (var i = 0; i < bs; i++)
                realExt ? rng.nextInt(256) : aReal[bs - 1],
            ];
            final lExt = [
              for (var i = 0; i < bs; i++)
                realExt ? rng.nextInt(256) : lReal[bs - 1],
            ];
            final cr = rng.nextInt(256);
            final a2 = [...aReal, ...aExt];
            final l2 = [...lReal, ...lExt];

            for (final filterType in [0, 1]) {
              for (var m = 1; m <= 8; m++) {
                for (var d = -3; d <= 3; d++) {
                  mode.put(m);
                  ad.put(d & 0xF);
                  above.put(packB(a2));
                  left.put(packB(l2));
                  corner.put(cr);
                  en.put(1);
                  ft.put(filterType);
                  await clk.nextPosedge;

                  final want = _gold['${bs}_$realExt']![gi++];
                  final pv = t.output('pred').value.toBigInt();
                  final got = [
                    for (var p = 0; p < bs * bs; p++)
                      ((pv >> (p * 8)) & BigInt.from(0xff)).toInt(),
                  ];
                  expect(
                    got,
                    equals(want),
                    reason:
                        'bs=$bs $tag ft=$filterType mode=$m delta=$d iter=$iter',
                  );
                }
              }
            }
          }
          await Simulator.endSimulation();
        },
      );
    }
  }
}
